        self.red_streaks = {symbol: 0 for symbol in self.symbols}

        self.previous_spy_sma = None
        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, slice):
        # Keep market-state quantities current for every ticker that has a bar.
        prior_spy_close = self.previous_closes[self.spy]
        today_red_streak_aapl = self.red_streaks[self.aapl]

        for symbol in self.symbols:
            if not slice.Bars.ContainsKey(symbol):
                continue

            bar = slice.Bars[symbol]
            previous_close = self.previous_closes[symbol]

            if previous_close is not None and bar.Close < previous_close:
                self.red_streaks[symbol] += 1
            else:
                self.red_streaks[symbol] = 0

            self.previous_closes[symbol] = bar.Close

            if symbol == self.spy:
                self.spy_sma.Update(bar.EndTime, bar.Close)
            elif symbol == self.aapl:
                self.aapl_rsi.Update(bar.EndTime, bar.Close)

        if slice.Bars.ContainsKey(self.aapl):
            today_red_streak_aapl = self.red_streaks[self.aapl]

        # Skip all rule evaluation if any subscribed ticker is missing today.
        if not all(slice.Bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        spy_close = slice.Bars[self.spy].Close
        aapl_close = slice.Bars[self.aapl].Close
        current_spy_sma = self.spy_sma.Current.Value

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            if self.spy_sma.IsReady:
                self.previous_spy_sma = current_spy_sma
            return

