            if data.Bars.ContainsKey(symbol):
                close = float(data.Bars[symbol].Close)

                if symbol == self.spy:
                    self.spy_closes.Add(close)

                elif symbol == self.aapl:
                    self._update_aapl_state(close)

        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        if not self.spy_closes.IsReady or not self.rsi_ready:
            return

        spy_close = float(data.Bars[self.spy].Close)
        aapl_close = float(data.Bars[self.aapl].Close)

        current_sma = sum(self.spy_closes[i] for i in range(100)) / 100.0
        previous_sma = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0
        previous_spy_close = self.spy_closes[1]

        spy_crosses_above = (
            previous_spy_close <= previous_sma and spy_close > current_sma
        )
        spy_crosses_below = (
            previous_spy_close >= previous_sma and spy_close < current_sma
        )

        # Evaluate sells before buys.
        if self.strategy_a_lot > 0 and spy_crosses_below:
            self.MarketOrder(self.spy, -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and self.aapl_rsi > 60:
            self.MarketOrder(self.aapl, -self.strategy_b_lot)
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_crosses_above:
            quantity = int(math.floor(0.40 * self.Portfolio.TotalPortfolioValue / spy_close))
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.strategy_a_lot = quantity

        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20_000:
                quantity = int(math.floor(20_000 / aapl_close))
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.strategy_b_lot = quantity

    def _update_aapl_state(self, close: float):
        if self.aapl_previous_close is not None:
            change = close - self.aapl_previous_close

            if close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            gain = max(change, 0.0)
            loss = max(-change, 0.0)

            if self.rsi_samples < self.rsi_period:
                self.rsi_gain_sum += gain
                self.rsi_loss_sum += loss
                self.rsi_samples += 1

                if self.rsi_samples == self.rsi_period:
                    self.rsi_average_gain = self.rsi_gain_sum / self.rsi_period
                    self.rsi_average_loss = self.rsi_loss_sum / self.rsi_period
                    self.rsi_ready = True
            else:
                self.rsi_average_gain = (
                    (self.rsi_average_gain * (self.rsi_period - 1)) + gain
                ) / self.rsi_period
                self.rsi_average_loss = (
                    (self.rsi_average_loss * (self.rsi_period - 1)) + loss
                ) / self.rsi_period

            if self.rsi_ready:
                if self.rsi_average_loss == 0:
                    self.aapl_rsi = 100.0
                else:
                    relative_strength = self.rsi_average_gain / self.rsi_average_loss
                    self.aapl_rsi = 100.0 - (100.0 / (1.0 + relative_strength))

        self.aapl_previous_close = close
