class IndependentDailyStrategies(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_closes = deque(maxlen=101)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data: Slice):
        self._update_market_state(data)

        if not all(symbol in data.Bars and data.Bars[symbol] is not None
                   for symbol in self.symbols.values()):
            return

        if not self._all_required_history_ready():
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        prices = list(self.spy_closes)
        yesterday_sma = sum(prices[-101:-1]) / Decimal(100)
        today_sma = sum(prices[-100:]) / Decimal(100)
        yesterday_close = prices[-2]

        spy_crosses_above = (
            yesterday_close <= yesterday_sma and spy_close > today_sma
        )
        spy_crosses_below = (
            yesterday_close >= yesterday_sma and spy_close < today_sma
        )

        # Sells are evaluated before buys.
        if self.strategy_a_lot > 0 and spy_crosses_below:
            self.MarketOrder(self.spy, -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and self.aapl_rsi.Current.Value > Decimal(60):
            self.MarketOrder(self.aapl, -self.strategy_b_lot)
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_crosses_above:
            quantity = int(
                (self.Portfolio.TotalPortfolioValue * Decimal("0.40")) / spy_close
            )
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.strategy_a_lot = quantity

        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
            purchase_amount = Decimal(20000)
            if self.Portfolio.Cash >= purchase_amount:
                quantity = int(purchase_amount / aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.strategy_b_lot = quantity

    def _update_market_state(self, data: Slice):
        if self.spy in data.Bars and data.Bars[self.spy] is not None:
            self.spy_closes.append(data.Bars[self.spy].Close)

        if self.aapl in data.Bars and data.Bars[self.aapl] is not None:
            close = data.Bars[self.aapl].Close
            self.aapl_rsi.Update(IndicatorDataPoint(data.Time, close))

            if self.previous_aapl_close is not None:
                if close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = close

    def _all_required_history_ready(self):
        return (
            len(self.spy_closes) == 101
            and self.aapl_rsi.IsReady
            and self.previous_aapl_close is not None
        )
